ModuleRegistry.prototype.STATUS.PAUSED = 'paused';
ModuleRegistry.prototype.pause = async function(name) {
    const mod = this._modules.get(name);
    if (!mod || mod.status !== this.STATUS.INITIALIZED) return false;
    try {
        if (typeof mod.instance.pause === 'function') await mod.instance.pause();
        mod.status = this.STATUS.PAUSED;
        return true;
    } catch (err) {
        mod.status = this.STATUS.ERROR;
        mod.error = err.message;
        return false;
    }
};
ModuleRegistry.prototype.resume = async function(name) {
    const mod = this._modules.get(name);
    if (!mod || mod.status !== this.STATUS.PAUSED) return false;
    try {
        if (typeof mod.instance.resume === 'function') await mod.instance.resume();
        mod.status = this.STATUS.INITIALIZED;
        return true;
    } catch (err) {
        mod.status = this.STATUS.ERROR;
        mod.error = err.message;
        return false;
    }
};

EventBus.prototype._maxListeners = 100;
const originalOn = EventBus.prototype.on;
EventBus.prototype.on = function(event, handler, options = {}) {
    const listeners = this._listeners.get(event);
    if (listeners && listeners.length >= this._maxListeners) {
        console.warn('[EventBus] 事件 "' + event + '" 的监听器数量超过最大限制 (' + this._maxListeners + ')');
    }
    return originalOn.call(this, event, handler, options);
};

Logger.prototype._log = function(level, module, message, data) {
    if (!this._enabled) return;
    const validLevels = ['debug', 'info', 'warn', 'error'];
    const safeLevel = validLevels.includes(level) ? level : 'debug';
    if (this._levels[safeLevel] < this._currentLevel) return;
    const ts = this._timestamp();
    const prefix = '[' + ts + '] [' + safeLevel.toUpperCase() + '] [' + module + ']';
    const consoleMethod = safeLevel === 'debug' ? 'log' : safeLevel;
    if (data !== undefined) {
        console[consoleMethod](prefix + ' ' + message, data);
    } else {
        console[consoleMethod](prefix + ' ' + message);
    }
};

function debounce(fn, delay = 300) {
    let timer = null;
    const debounced = function (...args) {
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => { fn.apply(this, args); timer = null; }, delay);
    };
    debounced.cancel = function() { if (timer) { clearTimeout(timer); timer = null; } };
    debounced.flush = function() { if (timer) { clearTimeout(timer); timer = null; fn(); } };
    return debounced;
}

function throttle(fn, interval = 200) {
    if (typeof interval !== 'number' || interval < 0) {
        console.warn('[throttle] interval 必须为非负数，已使用默认值 200');
        interval = 200;
    }
    let lastTime = 0;
    return function (...args) {
        const now = Date.now();
        if (now - lastTime >= interval) { lastTime = now; fn.apply(this, args); }
    };
}

ModuleRegistry.prototype.destroyAll = async function() {
    const destroyed = new Set();
    const order = [];
    const canDestroy = (name) => {
        const mod = this._modules.get(name);
        if (!mod || destroyed.has(name)) return false;
        for (const [otherName, otherMod] of this._modules) {
            if (destroyed.has(otherName)) continue;
            if (otherMod.dependencies && otherMod.dependencies.includes(name)) return false;
        }
        return true;
    };
    while (destroyed.size < this._modules.size) {
        let found = false;
        for (const [name] of this._modules) {
            if (canDestroy(name)) { order.push(name); destroyed.add(name); found = true; break; }
        }
        if (!found) break;
    }
    for (const name of order) { await this.destroy(name); }
};

EventBus.prototype.getHistory = function() {
    return this._history.map(item => ({
        ...item,
        data: item.data !== undefined && typeof item.data === 'object' && item.data !== null
            ? JSON.parse(JSON.stringify(item.data))
            : item.data
    }));
};

let idCounter = 0;
function generateId(prefix = '') {
    const timestamp = Date.now().toString(36);
    const counter = (idCounter++).toString(36);
    const random = Math.random().toString(36).substring(2, 8);
    return prefix ? prefix + '_' + timestamp + '_' + counter + '_' + random : timestamp + '_' + counter + '_' + random;
}
